const fs=require('fs'),path=require('path');const base='data/raw/champions-results/2026-10-22';
const events=JSON.parse(fs.readFileSync(base+'/probe-1.txt')).events;const cfg=require('../data/sources/champions-pilot-match-stats-2025-27.json');const calendar=require('../data/sources/champions-league-2026-27.json');
const jobs=calendar.fixtures.filter(f=>f.matchday<=3).map(f=>{let h=cfg.teams.find(t=>t.name===f.homeTeam),a=cfg.teams.find(t=>t.name===f.awayTeam);if(!h||!a)throw Error('team mapping '+f.id);let e=events.find(e=>e.date.slice(0,10)===f.date&&e.competitions[0].competitors.some(c=>c.homeAway==='home'&&c.id===h.espnTeamId)&&e.competitions[0].competitors.some(c=>c.homeAway==='away'&&c.id===a.espnTeamId));if(!e)throw Error('event missing '+f.id);return {fixtureId:f.id,eventId:e.id,date:f.date,homeTeamId:h.id,awayTeamId:a.id};});
(async()=>{let index=0;await Promise.all(Array.from({length:6},async()=>{while(index<jobs.length){const j=jobs[index++],file=base+'/'+j.eventId+'.json';if(fs.existsSync(file))continue;const url='https://site.api.espn.com/apis/site/v2/sports/soccer/uefa.champions/summary?event='+j.eventId;try{let r=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('HTTP '+r.status);let payload=await r.json();if(!payload.header||!payload.rosters)throw Error('Incomplete summary');fs.writeFileSync(file,JSON.stringify({url,retrievedAt:new Date().toISOString(),league:'uefa.champions',season:'2026-27',eventId:j.eventId,eventDate:j.date,payload}));console.log(j.fixtureId,payload.rosters.map(r=>r.roster?.length));}catch(e){j.error=e.message}}}));fs.writeFileSync(base+'/manifest.json',JSON.stringify({jobs},null,2));})().catch(e=>{console.error(e);process.exitCode=1});
